/* STM32CubeU5 HAL timer test.
 *
 * Unmodified HAL. TIM6 is the HAL time base, from the HAL template
 * stm32u5xx_hal_timebase_tim_template.c (TIM6 update interrupt every 1 ms calls HAL_IncTick),
 * as generated by STM32CubeMX when SysTick is used by an RTOS. The system clock is raised to
 * 160 MHz, so HAL_InitTick reconfigures TIM6 for the new clock. TIM4 channel 4 generates a
 * 1 Hz square wave in PWM mode 1: 10 kHz counter clock, period 10000, pulse 5000.
 * Checks are stored in global variables read by the robot test. */

#include "clock_160mhz.h"

TIM_HandleTypeDef htim4;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t delayDone;

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

void HAL_TIM_PWM_MspInit(TIM_HandleTypeDef *htim)
{
    if (htim->Instance == TIM4)
    {
        __HAL_RCC_TIM4_CLK_ENABLE();
    }
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);

    /* HAL_Delay counts TIM6 ticks. */
    HAL_Delay(10);
    delayDone = 1u;

    const uint32_t counterHz = 10000u;
    htim4.Instance = TIM4;
    htim4.Init.Prescaler = (HAL_RCC_GetPCLK1Freq() / counterHz) - 1u;
    htim4.Init.CounterMode = TIM_COUNTERMODE_UP;
    htim4.Init.Period = counterHz - 1u;
    htim4.Init.ClockDivision = TIM_CLOCKDIVISION_DIV1;
    htim4.Init.AutoReloadPreload = TIM_AUTORELOAD_PRELOAD_ENABLE;
    check(HAL_TIM_PWM_Init(&htim4), 3);

    TIM_OC_InitTypeDef output = {0};
    output.OCMode = TIM_OCMODE_PWM1;
    output.Pulse = counterHz / 2u;
    output.OCPolarity = TIM_OCPOLARITY_HIGH;
    output.OCFastMode = TIM_OCFAST_DISABLE;
    check(HAL_TIM_PWM_ConfigChannel(&htim4, &output, TIM_CHANNEL_4), 4);
    check(HAL_TIM_PWM_Start(&htim4, TIM_CHANNEL_4), 5);

    step = 6;
    for (;;)
    {
    }
}
